// Highlight Factory app mark — geometry taken verbatim from the source export
// (also kept at public/brand/mark.svg). Do not redraw it; if the logo changes,
// re-export and replace MARK_PATH_D / MARK_DOT below.
//
// Notes on the source file:
//  • Native viewBox is 27 x 28 (not square).
//  • The export nests two groups whose transforms net out to translate(.3965,.5);
//    that's flattened into MARK_TRANSFORM here.
//  • The brackets are filled shapes with fill-rule evenodd (not dashed strokes).
//  • The centre dot sits slightly up-and-right of centre by design (cx 15, cy 12).

export const MARK_W = 27;
export const MARK_H = 28;

// Net of the source file's nested group transforms: translate(-24,-87.5) then
// translate(24.3965, 88).
export const MARK_TRANSFORM = "translate(0.3965, 0.5)";

export const MARK_DOT = { cx: 15, cy: 12, r: 5 };

/** The mark's true coral. Distinct from the site's --brand plum. */
export const BRAND_CORAL = "#DB6A59";

