/**
 * The mark's inner contents, for embedding inside another <svg> (e.g. the
 * factory illustration). Wrap in a <g> with your own translate/scale.
 * `bracketFill` defaults to currentColor so the brackets adapt to the theme.
 */
export function MarkShapes({ bracketFill = "currentColor", dotFill = BRAND_CORAL }) {
  return (
    <g transform={MARK_TRANSFORM}>
      <path d={MARK_PATH_D} fill={bracketFill} fillRule="evenodd" />
      <circle cx={MARK_DOT.cx} cy={MARK_DOT.cy} r={MARK_DOT.r} fill={dotFill} />
    </g>
  );
}

/**
 * Standalone mark. `size` sets the height; width follows the native 27:28
 * ratio so the artwork is never distorted.
 */
export default function BrandMark({ size = 30, style, title, bracketFill, dotFill }) {
  return (
    <svg
      width={(size * MARK_W) / MARK_H}
      height={size}
      viewBox={`0 0 ${MARK_W} ${MARK_H}`}
      fill="none"
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
      aria-label={title}
      style={style}
    >
      {title && <title>{title}</title>}
      <MarkShapes bracketFill={bracketFill} dotFill={dotFill} />
    </svg>
  );
}
